import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"ADR-0019 — Embedded search, export PDF/HTML e impostazioni residue (M6-WP6)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0019-embedded-search-export-details.md","filePath":"adr/0019-embedded-search-export-details.md"}'),n={name:"adr/0019-embedded-search-export-details.md"};function r(d,e,c,s,l,m){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0019-—-embedded-search-export-pdf-html-e-impostazioni-residue-m6-wp6" tabindex="-1">ADR-0019 — Embedded search, export PDF/HTML e impostazioni residue (M6-WP6) <a class="header-anchor" href="#adr-0019-—-embedded-search-export-pdf-html-e-impostazioni-residue-m6-wp6" aria-label="Permalink to &quot;ADR-0019 — Embedded search, export PDF/HTML e impostazioni residue (M6-WP6)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.2.1, §2.3.2 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-24</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>matrice §2.2.1 (Embedded search, Export P1), §2.6 impostazioni; D-01, D-06</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>M6-WP6 chiude le righe P1 &quot;Embedded search (code block <code>query</code>)&quot;, &quot;Export PDF/HTML autonomo&quot; e le impostazioni rimaste fuori da M1.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong>Blocco <code>query</code>.</strong> Il corpo usa la stessa sintassi del pannello di ricerca (§2.4). Righe opzionali riconosciute dalla sola chiave: <code>sort: relevance|name|modified</code>, <code>limit: N</code> (tetto rigido, max 500), <code>view: list|cards</code>, <code>context: on|off</code> (riga di contesto con evidenziazione), <code>self: include|exclude</code>. Le altre righe formano la query. Senza <code>limit</code> i risultati sono a pagine da 100 con &quot;mostra altri&quot;. Usa il binding <code>SearchAPI.Query</code> esistente (nessun Go nuovo) tramite <code>QueryObserver</code> sul <code>queryClient</code> condiviso: la chiave inizia con <code>[&#39;search&#39;, vaultId]</code>, quindi si aggiorna con le stesse invalidazioni del pannello. Errori di query inline (<code>role=alert</code>). La nota ospitante è esclusa di default (impostazione <code>queryIncludeHost</code>, override <code>self:</code>); l&#39;esclusione è lato client, quindi con <code>limit</code> si richiede un risultato in più. Live Preview: widget di blocco (sorgente visibile con il cursore dentro); Reading: <code>hydrate</code>.</p><p><strong>Export.</strong> Un solo renderer (<code>export/render.ts</code>) parte dal reading view e rende il documento indipendente: immagini/disegni/canvas come data URI (tetto 8 MB per file, 48 MB totali; oltre, esclusi e segnalati), note incorporate in linea, math come MathML, Mermaid come SVG in tema chiaro, HTML ri-sanificato con DOMPurify. Scelta sui link: i wikilink diventano testo semplice, salvo i link a un&#39;intestazione/blocco della stessa nota (ancore interne); link http(s)/mailto restano link. Audio, video, PDF e immagini remote sono omessi e segnalati. I blocchi <code>query</code> restano come codice.</p><ul><li><strong>HTML</strong>: <code>ExportAPI.SaveHTML</code> (Go) mostra il dialogo nativo, scrive in modo atomico (tmp + rename) e rifiuta destinazioni dentro il vault (anche i vault in sola lettura sono esportabili, mai modificati). Il Go rifiuta script, handler, iframe e risorse remote come seconda barriera; il file ha CSP <code>default-src &#39;none&#39;</code> e <code>prefers-color-scheme</code>.</li><li><strong>PDF</strong>: layer di stampa chiaro (<code>#memobrain-print</code>, sempre tema chiaro, UI nascosta in <code>@media print</code>) e <code>ExportAPI.Print</code> → <code>runtime.WindowPrint</code> (Wails 2.12: macOS <code>NSPrintOperation</code>, Windows/Linux <code>window.print()</code>); il PDF si ottiene con &quot;Salva come PDF&quot; del dialogo di sistema. Wails v2 non offre print-to-PDF senza dialogo.</li></ul><p><strong>Impostazioni aggiunte</strong> (<code>editor.json</code>, bloccabili dalla config): <code>newNoteLocation</code> (cartella indicata / accanto alla nota), <code>attachmentLocation</code> (cartella / accanto alla nota / sottocartella della nota), <code>confirmDelete</code>, <code>queryIncludeHost</code>. Già presenti: cartella nuove note/allegati, formato link, modalità cestino, vista predefinita. <strong>Non fatte:</strong> aggiornamento automatico dei link al rinomina on/off, file esclusi, &quot;usa wikilink vs link Markdown&quot; (non elencate nello spec; da valutare). Daily notes: WP3a.</p><h2 id="limiti-per-piattaforma" tabindex="-1">Limiti per piattaforma <a class="header-anchor" href="#limiti-per-piattaforma" aria-label="Permalink to &quot;Limiti per piattaforma&quot;">​</a></h2><p>Non verificabile in questo ambiente (nessuna GUI Wails): macOS forza orientamento orizzontale e margini 0 nel pannello di stampa (si cambia nel pannello; i margini sono nel padding del documento); Windows/Linux dipendono dal dialogo di WebView2/WebKitGTK. Da provare a mano (<code>docs/qa/m6-search-export.md</code>).</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>PDF generato in Go/headless Chrome</strong> — dipendenza pesante, contro l&#39;architettura chiusa.</li><li><strong>KaTeX HTML+CSS nell&#39;export</strong> — richiede font incorporati (centinaia di KB); MathML è nativo nei browser moderni.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p>Un solo percorso di rendering per stampa ed HTML. Il risultato PDF dipende dal dialogo di sistema. L&#39;esclusione della nota ospitante è approssimata oltre il limite di pagina.</p>',15)])])}const h=o(n,[["render",r]]);export{u as __pageData,h as default};
